G=load()
for name,g,out in [('d1',di1,do1),('d2',di2,do2),('d3',di3,do3)]:
    h=len(g); w=len(g[0])
    def vis(i,j):
        res={}
        lab={'U':(-1,0),'D':(1,0),'L':(0,-1),'R':(0,1)}
        for dn,step in lab.items():
            a,b=i+step[0],j+step[1]; seen=False
            while 0<=a<h and 0<=b<w:
                if g[a][b]==5: res[dn]=1; seen=True; break
                a+=step[0]; b+=step[1]
            if not seen: res[dn]=None
        return res
    stats={'X':Counter(),'7':Counter(),'O':Counter()}
    for i in range(h):
        for j in range(w):
            if g[i][j]==0:
                v=vis(i,j)
                n=sum(1 for x in v.values() if x is not None)
                opp = ('U' in v and 'D' in v) or ('L' in v and 'R' in v)
                tag='X' if out[i][j]==8 else ('7' if out[i][j]==7 else 'O')
                stats[tag][(n,opp)]+=1
    print(name,'X:',dict(stats['X']))
    print(name,'7:',dict(stats['7']))
    print(name,'O top6:',dict(stats['O'].most_common(6)))

