        for j in (0,w-1):
            if g[i][j]==0: seen.add((i,j));q.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if g[i][j]==0: seen.add((i,j));q.append((i,j))
    while q:
        a,b=q.popleft()
        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
